<?php
require __DIR__.'/../app/admin.php';$user=ij_require_user();require __DIR__.'/../app/home-slots.php';$homeSlots=ij_home_slots();
$db=ij_db();$categories=$db->query('SELECT id,name FROM categories ORDER BY id')->fetchAll();
$query=is_string($_GET['q'] ?? null) ? mb_substr(trim($_GET['q']),0,190) : '';
$category=is_string($_GET['categoria'] ?? null) ? $_GET['categoria'] : '';
if ($category!=='opinion' && !in_array($category,array_map(fn($c)=>(string)$c['id'],$categories),true)) $category='';
$where=[];$params=[];
if ($category==='opinion') $where[]="p.type='opinion'";
elseif ($category!=='') {$where[]="p.type='news' AND p.category_id=?";$params[]=$category;}
if ($query!=='') {$where[]="(p.title LIKE ? ESCAPE '!' OR a.name LIKE ? ESCAPE '!')";$term='%'.str_replace(['!','%','_'],['!!','!%','!_'],$query).'%';$params[]=$term;$params[]=$term;}
$from=' FROM posts p JOIN categories c ON c.id=p.category_id LEFT JOIN authors a ON a.id=p.author_id'.($where ? ' WHERE '.implode(' AND ',$where) : '');
$stmt=$db->prepare('SELECT COUNT(*)'.$from);$stmt->execute($params);$total=(int)$stmt->fetchColumn();
$pages=max(1,(int)ceil($total/30));$page=min($pages,max(1,(int)(is_scalar($_GET['pagina'] ?? null) ? $_GET['pagina'] : 1)));$offset=($page-1)*30;
$stmt=$db->prepare('SELECT p.*,c.name category_name'.$from.' ORDER BY COALESCE(p.published_at,p.created_at) DESC,p.id DESC LIMIT 30 OFFSET '.$offset);$stmt->execute($params);$posts=$stmt->fetchAll();
function ij_posts_filter_url(int $page): string {global $query,$category;return '/admin/?'.http_build_query(['q'=>$query,'categoria'=>$category,'pagina'=>$page]);}
$pageTitle='Publicaciones';require __DIR__.'/_head.php';
?>
<div class="toolbar"><p>Noticias y columnas de opinión. Los borradores solo se ven desde el panel.</p><a class="button primary" href="/admin/editar.php">Nueva publicación</a></div>
<?php if (isset($_GET['guardado'])): ?><p class="success" role="status"><?= ij_e(['borrador'=>'Borrador guardado. Solo lo podés ver desde el panel.','publicada'=>'Publicación visible en el portal.','actualizada'=>'Cambios guardados.','programada'=>'Publicación programada.','oculta'=>'Publicación oculta. Se conserva como borrador.','eliminada'=>'Publicación eliminada.'][is_string($_GET['guardado']) ? $_GET['guardado'] : ''] ?? 'Publicación guardada.') ?></p><?php endif; ?>
<form class="publication-filters" method="get" action="/admin/" role="search"><label>Buscar publicación<input type="search" name="q" maxlength="190" value="<?= ij_e($query) ?>" placeholder="Título o autor"></label><label>Categoría<select name="categoria"><option value="">Todas las categorías</option><?php foreach($categories as $c):?><option value="<?= (int)$c['id'] ?>" <?= $category===(string)$c['id']?'selected':'' ?>><?= ij_e($c['name']) ?></option><?php endforeach;?><option value="opinion" <?= $category==='opinion'?'selected':'' ?>>Opinión</option></select></label><button class="primary">Buscar</button><?php if($query!=='' || $category!==''):?><a class="button" href="/admin/">Limpiar filtros</a><?php endif;?></form>
<p class="help">De más reciente a más antigua por fecha de publicación. Los borradores sin fecha usan su fecha de creación.</p>
<p class="help" role="status"><?= $total ?> <?= $total===1?'publicación encontrada':'publicaciones encontradas' ?></p>
<?php if (!$posts): ?><p class="empty"><?= $query!=='' || $category!=='' ? 'No hay publicaciones que coincidan. Probá otra búsqueda o limpiá los filtros.' : 'Todavía no hay publicaciones. Creá la primera noticia para comenzar.' ?></p><?php endif; ?>
<div class="post-list"><?php foreach ($posts as $p): $postSlot=array_search((int)$p['id'],$homeSlots,true); ?><article class="post-row"><div><span class="tag"><?= $p['type']==='opinion' ? 'Opinión' : ij_e($p['category_name']) ?></span><h2><a href="/admin/editar.php?id=<?= $p['id'] ?>"><?= ij_e($p['title']) ?></a></h2><p><?= $p['status']==='draft' ? 'Borrador' : ($p['published_at']>ij_now() ? 'Programada · '.ij_date($p['published_at']) : 'Publicada · '.ij_date($p['published_at'])) ?><?= $postSlot!==false ? ' · '.ij_e(ij_slot_names()[$postSlot]).($p['status']!=='published' || $p['published_at']>ij_now() ? ' (oculta)' : '') : '' ?><?= $p['in_context'] ? ' · En contexto' : '' ?></p></div><div class="post-actions"><a class="button primary" href="/admin/editar.php?id=<?= $p['id'] ?>">Editar</a><a class="button" href="/admin/preview.php?id=<?= $p['id'] ?>" target="_blank" rel="noopener">Vista previa</a><?php if($p['status']==='published'):?><a class="button" href="/admin/publicacion-accion.php?id=<?= (int)$p['id'] ?>&amp;accion=hide">Ocultar</a><?php else:?><form method="post" action="/admin/publicacion-accion.php?id=<?= (int)$p['id'] ?>&amp;accion=publish"><input type="hidden" name="csrf" value="<?= ij_csrf() ?>"><button type="submit">Publicar</button></form><?php endif;?><a class="button button-danger" href="/admin/publicacion-accion.php?id=<?= (int)$p['id'] ?>&amp;accion=delete">Eliminar</a></div></article><?php endforeach; ?></div>
<?php if($pages>1):?><nav class="toolbar" aria-label="Páginas de publicaciones"><?php if($page>1):?><a class="button" href="<?= ij_e(ij_posts_filter_url($page-1)) ?>">Anterior</a><?php endif;?><span>Página <?= $page ?> de <?= $pages ?></span><?php if($page<$pages):?><a class="button" href="<?= ij_e(ij_posts_filter_url($page+1)) ?>">Siguiente</a><?php endif;?></nav><?php endif;?>
<?php require __DIR__.'/_foot.php'; ?>
